// bendrt.js: runtime for JavaScript generated by bendc --js.
//
// Values are what the official JS target uses, so effect files written for
// it work unchanged: a U32 or F32 is a number, a Nat a BigInt, a Bool a
// boolean, a Char a string of one code point, a String a string, and any
// other constructor an object {$: "Name", field: value, ...}. A function is
// a curried JS function. Effects are requests the event loop answers, with
// the official helpers (io_done, io_fail, io_tup, io_sys, io_park_on, ...).

"use strict";

// Failures
// ========

function bend_fail(msg) {
  throw "bend: " + msg;
}

// Strings and characters
// ======================

function char_new(code) {
  if (code > 0x10FFFF || (code >= 0xD800 && code <= 0xDFFF)) {
    bend_fail(code + " is not a Unicode scalar value");
  }
  return String.fromCodePoint(code);
}

// The first code point of a non-empty string, as a Char, and the rest.
function str_head(s) {
  const c = s.codePointAt(0);
  return String.fromCodePoint(c);
}

function str_tail(s) {
  return s.slice(s.codePointAt(0) > 0xFFFF ? 2 : 1);
}

function str_cons(c, s) {
  return c + s;
}

// Natives: U32
// ============

const F_U32_dinc = (a) => (a + 1) >>> 0;
const F_U32_dadd = (a, b) => (a + b) >>> 0;
const F_U32_dsub = (a, b) => (a - b) >>> 0;
const F_U32_dmul = (a, b) => Math.imul(a, b) >>> 0;
const F_U32_ddiv = (a, b) => (b === 0 ? 0 : Math.floor(a / b) >>> 0);
const F_U32_dmod = (a, b) => (b === 0 ? a : a % b);
const F_U32_dnot = (a) => ~a >>> 0;
const F_U32_dand = (a, b) => (a & b) >>> 0;
const F_U32_dor = (a, b) => (a | b) >>> 0;
const F_U32_dxor = (a, b) => (a ^ b) >>> 0;
const F_U32_dshl = (a) => (a << 1) >>> 0;
const F_U32_dshr = (a) => a >>> 1;
const F_U32_dshln = (a, n) => (n >= 32n ? 0 : (a << Number(n)) >>> 0);
const F_U32_dshrn = (a, n) => (n >= 32n ? 0 : a >>> Number(n));
const cmp_new = (a, b) => ({ $: a < b ? "LT" : a === b ? "EQ" : "GT" });
const F_U32_dcmp = cmp_new;
const F_U32_dis__eq = (a, b) => a === b;
const F_U32_dis__ne = (a, b) => a !== b;
const F_U32_dis__lt = (a, b) => a < b;
const F_U32_dis__le = (a, b) => a <= b;
const F_U32_dis__gt = (a, b) => a > b;
const F_U32_dis__ge = (a, b) => a >= b;
const F_U32_dis__zero = (a) => a === 0;
const F_U32_dis__even = (a) => (a & 1) === 0;
const F_U32_dto__nat = (a) => BigInt(a);
const F_U32_dfrom__nat = (n) => Number(BigInt.asUintN(32, n));
const F_U32_dmin = (a, b) => (a < b ? a : b);
const F_U32_dmax = (a, b) => (a < b ? b : a);
const F_U32_dpow = (a, n) => {
  let r = 1n;
  let b = BigInt(a);
  const m = 1n << 32n;
  for (let e = n; e > 0n; e >>= 1n) {
    if (e & 1n) r = (r * b) % m;
    b = (b * b) % m;
    if (b === 0n && e > 1n) return (e & 1n) ? Number(r) : 0;
  }
  return Number(r);
};
const F_U32_dlog2 = (n) => (n <= 1 ? 0 : 31 - Math.clz32(n));
const F_U32_dto__f32 = (a) => Math.fround(a);

// Natives: Nat (BigInt, unbounded)
// ================================

const F_Nat_ddouble = (a) => a * 2n;
const F_Nat_dadd = (a, b) => a + b;
const F_Nat_dsub = (a, b) => (a > b ? a - b : 0n);
const F_Nat_dmul = (a, b) => a * b;
const nat_divmod = (a, b) => (b === 0n ? { $: "Tuple", fst: 0n, snd: a } : { $: "Tuple", fst: a / b, snd: a % b });
const F_Nat_ddivmod = nat_divmod;
const F_Nat_ddiv = (a, b) => (b === 0n ? 0n : a / b);
const F_Nat_dmod = (a, b) => (b === 0n ? a : a % b);
const F_Nat_dcmp = cmp_new;
const F_Nat_dis__eq = (a, b) => a === b;
const F_Nat_dis__ne = (a, b) => a !== b;
const F_Nat_dis__lt = (a, b) => a < b;
const F_Nat_dis__le = (a, b) => a <= b;
const F_Nat_dis__gt = (a, b) => a > b;
const F_Nat_dis__ge = (a, b) => a >= b;
const F_Nat_dmin = (a, b) => (a < b ? a : b);
const F_Nat_dmax = (a, b) => (a < b ? b : a);
const F_Nat_dpow = (a, n) => a ** n;
const F_Nat_dshow = (a) => a.toString();

// Natives: F32
// ============

const fr = Math.fround;
const F_F32_dadd = (a, b) => fr(a + b);
const F_F32_dsub = (a, b) => fr(a - b);
const F_F32_dmul = (a, b) => fr(a * b);
const F_F32_ddiv = (a, b) => fr(a / b);
const F_F32_dmod = (a, b) => fr(a % b);
const F_F32_dpow = (a, b) => fr(a ** b);
const F_F32_datan2 = (a, b) => fr(Math.atan2(a, b));
const F_F32_dis__eq = (a, b) => a === b;
const F_F32_dis__ne = (a, b) => a !== b;
const F_F32_dis__lt = (a, b) => a < b;
const F_F32_dis__le = (a, b) => a <= b;
const F_F32_dis__gt = (a, b) => a > b;
const F_F32_dis__ge = (a, b) => a >= b;
const F_F32_dneg = (a) => fr(-a);
const F_F32_dabs = (a) => fr(Math.abs(a));
const F_F32_dsqrt = (a) => fr(Math.sqrt(a));
const F_F32_dexp = (a) => fr(Math.exp(a));
const F_F32_dlog = (a) => fr(Math.log(a));
const F_F32_dlog2 = (a) => fr(Math.log2(a));
const F_F32_dlog10 = (a) => fr(Math.log10(a));
const F_F32_dsin = (a) => fr(Math.sin(a));
const F_F32_dcos = (a) => fr(Math.cos(a));
const F_F32_dtan = (a) => fr(Math.tan(a));
const F_F32_dasin = (a) => fr(Math.asin(a));
const F_F32_dacos = (a) => fr(Math.acos(a));
const F_F32_datan = (a) => fr(Math.atan(a));
const F_F32_dsinh = (a) => fr(Math.sinh(a));
const F_F32_dcosh = (a) => fr(Math.cosh(a));
const F_F32_dtanh = (a) => fr(Math.tanh(a));
const F_F32_dfloor = (a) => fr(Math.floor(a));
const F_F32_dceil = (a) => fr(Math.ceil(a));
const F_F32_dtrunc = (a) => fr(Math.trunc(a));
const F_F32_dbits = (a) => new Uint32Array(new Float32Array([a]).buffer)[0];
const F_F32_dto__u32 = (a) => (a <= 0 || a !== a ? 0 : a >= 4294967295 ? 4294967295 : Math.trunc(a) >>> 0);

// The shortest text that reads back.
function f32_show(x) {
  if (x !== x) return "nan";
  if (!Number.isFinite(x)) return x < 0 ? "-inf" : "inf";
  if (Object.is(x, -0)) return "-0";
  let s = "x";
  for (let p = 1; p <= 9 && Math.fround(Number(s)) !== x; p += 1) {
    s = String(Number(x.toExponential(p - 1)));
  }
  return s;
}
const F_F32_dshow = (a) => f32_show(a);

function F_F32_dread(s) {
  const re = /^\s*[+-]?((\d+\.?\d*|\.\d+)(e[+-]?\d+)?|inf(inity)?|nan)$/i;
  const v = Number(s.replace(/inf\w*/i, "Infinity"));
  return re.test(s) ? { $: "Some", value: Math.fround(v) } : { $: "None" };
}

// Printing values (a main that is not IO)
// =======================================

function show_chr(c, q) {
  const k = { 10: "n", 9: "t", 13: "r", 0: "0", 92: "\\" }[c] ?? (c === q.codePointAt(0) ? q : null);
  return k !== null ? "\\" + k
    : c < 32 || c === 127 || (c >= 0xD800 && c <= 0xDFFF) ? "\\u{" + c.toString(16) + "}"
    : String.fromCodePoint(c);
}
const pr_u32 = (v) => String(v);
const pr_nat = (v) => v + "n";
const pr_f32 = (v) => f32_show(v).replace(/^-?\d+(?=e|$)/, "$&.0");
const pr_char = (v) => "'" + show_chr(v.codePointAt(0), "'") + "'";
const pr_str = (v) => '"' + [...v].map((c) => show_chr(c.codePointAt(0), '"')).join("") + '"';

// Effects
// =======

function io_out(fd, data) {
  const fs = require("fs");
  let at = 0;
  while (at < data.length) {
    try {
      at += fs.writeSync(fd, data, at, data.length - at);
    } catch (e) {
      if (e.code === "EAGAIN" || e.code === "EINTR") continue;
      process.exit(1);
    }
  }
}

function io_errs(message) {
  io_out(2, io_bytes(message + "\n"));
}

// libc through bun:ffi (the effects that make system calls need Bun).
function io_sys() {
  if (globalThis.BEND_SYS === undefined) {
    const ffi = require("bun:ffi");
    const mac = process.platform === "darwin";
    const err = mac ? "__error" : "__errno_location";
    const sel = mac ? "select$DARWIN_EXTSN" : "select";
    const T = { i: "i32", u: "u32", U: "u64", I: "i64", p: "ptr", c: "cstring" };
    const vari = mac && process.arch === "arm64";
    const decls = ("socket:iii>i bind:ipu>i listen:ii>i connect:ipu>i accept:ipp>i send:ipUi>I" +
      " recv:ipUi>I read:ipU>I pread:ipUI>I sendto:ipUipu>I recvfrom:ipUipp>I close:i>i" +
      " setsockopt:iiipu>i " + sel + ":ipppp>i" + (vari ? " fcntl:iiiiiiiii>i" : " fcntl:iii>i") +
      " getsockopt:iiipp>i strerror:i>c " + err + ":>p").split(" ");
    const lib = ffi.dlopen(mac ? "libSystem.dylib" : "libc.so.6", Object.fromEntries(decls.map((s) => {
      const [name, args, ret] = s.split(/[:>]/);
      return [name, { args: [...args].map((a) => T[a]), returns: T[ret] }];
    }))).symbols;
    const fcntl = (fd, cmd, arg) => (vari ? lib.fcntl(fd, cmd, 0, 0, 0, 0, 0, 0, arg) : lib.fcntl(fd, cmd, arg));
    globalThis.BEND_SYS = { ...lib, fcntl, select: lib[sel], ptr: ffi.ptr, mac,
      errno: () => ffi.read.i32(lib[err](), 0) };
  }
  return globalThis.BEND_SYS;
}

function io_fail(code) {
  let text = "error " + code;
  try {
    text = String(io_sys().strerror(code));
  } catch (e) {
  }
  return { $: "Fail", error: io_tup(code >>> 0, text) };
}

function io_done(value) {
  return { $: "Done", value };
}

function io_tup(...xs) {
  return xs.reduceRight((snd, fst) => ({ $: "Tuple", fst, snd }));
}

function io_bytes(text) {
  return new TextEncoder().encode(text);
}

function io_text(b, n) {
  return new TextDecoder("utf-8", { ignoreBOM: true }).decode(b.subarray(0, n));
}

function io_addr(host, port) {
  const part = host.split(".");
  const deci = (p) => /^(0|[1-9]\d{0,2})$/.test(p) && Number(p) < 256;
  if (port > 65535 || part.length !== 4 || !part.every(deci)) return null;
  const b = new Uint8Array(16);
  const head = io_sys().mac ? [16, 2] : [2, 0];
  b.set([...head, port >> 8, port & 255, ...part.map(Number)]);
  return b;
}

// A computation to run: fun applied to arg is its next request.
function io_push(fun, arg, fresh) {
  const io = globalThis.BEND_IO;
  io.runs.push({ fun, arg });
  io.live += fresh ? 1 : 0;
}

function io_wait(io) {
  const soon = io.waits.reduce((m, w) => Math.min(m, w.at ?? m), Infinity);
  const ms = soon === Infinity ? -1 : Math.max(0, Math.ceil(soon - performance.now()));
  const fds = io.waits.filter((w) => w.fd !== undefined);
  if (fds.length === 0) {
    // Only deadlines: sleep until the first one.
    if (ms > 0) Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
  } else {
    const top = fds.reduce((m, w) => Math.max(m, w.fd), 0);
    const len = (top >> 6 << 3) + 8;
    const set = new Uint8Array(2 * len);
    const at = (w) => (w.out ? len : 0) + (w.fd >> 3);
    for (const w of fds) set[at(w)] |= 1 << (w.fd & 7);
    const tv = new BigInt64Array([BigInt(ms / 1000 | 0), BigInt(ms % 1000 * 1000)]);
    const sys = io_sys();
    sys.select(top + 1, sys.ptr(set), sys.ptr(set, len), null, ms < 0 ? null : sys.ptr(tv));
    io.ready = (w) => set[at(w)] & 1 << (w.fd & 7);
  }
  const now = performance.now();
  io.waits = io.waits.filter((w) => {
    const ready = w.at <= now || (w.fd !== undefined && io.ready !== undefined && io.ready(w));
    if (ready) io_push(io_wake, w, false);
    return !ready;
  });
  io.ready = undefined;
}

// Resumes k with more's value; undefined means re-parked.
function io_wake(w) {
  const x = w.more();
  return x === undefined ? undefined : w.k(x);
}

// Parks for read/write (out) or a deadline at (performance.now()).
function io_park_on(fd, out, k, more, at) {
  globalThis.BEND_IO.waits.push({ fd, out, k, more, at });
}

function io_run(m) {
  const io = { runs: [], live: 0, waits: [] };
  globalThis.BEND_IO = io;
  io_push(m(null), (x) => ({ $: "Emit", value: x }), true);
  for (;;) {
    if (io.runs.length === 0) {
      if (io.live === 0) return 0;
      if (io.waits.length === 0) {
        io_errs("bend: deadlock: every computation waits on a channel");
        return 1;
      }
      io_wait(io);
      continue;
    }
    const s = io.runs.shift();
    let op = s.fun(s.arg);
    // An IO value from an effect (IO.spawn's) takes its erased type first.
    if (typeof op === "function") op = op(s.arg);
    while (op !== undefined) {
      if (op.$ === "Emit") {
        io.live -= 1;
        break;
      }
      if (op.$ === "Halt") {
        io_errs(op.message);
        return op.code;
      }
      if (op.run === undefined) bend_fail("an effect with no JS implementation: " + op.name);
      const need = op.need?.() ?? {};
      if (need.time || need.read) {
        const o = op;
        const more = () => o.run(...o.args, o.kont);
        io_park_on(need.read ? op.args[0] : undefined, false, op.kont, more,
          need.read ? undefined : performance.now() + Number(op.args[0]));
        break;
      }
      const x = op.run(...op.args, op.kont);
      if (x === undefined) break;
      op = op.kont(x);
    }
  }
}

// A request for effect e with arguments args, continued by k.
function io_req(e, name, args, k) {
  return { $: "$REQ", name, run: e?.run, need: e?.need, args, kont: k };
}

// Chan
// ----

const CHAN_RECV = Symbol();

function chan_wake(row, x) {
  const w = row.wait.shift();
  io_push(w.cont, x, false);
  return w.item;
}

function chan_take(row) {
  const v = row.ring.shift();
  if (row.wait.length > 0) row.ring.push(chan_wake(row, true));
  return v;
}

function chan_shut(row) {
  row.shut = true;
  while (row.wait.length > 0) {
    chan_wake(row, row.wait[0].item === CHAN_RECV ? { $: "None" } : false);
  }
}

// Entry points
// ============

let cli_args = [];

function cli(argv) {
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === "--") {
      cli_args.push(...argv.slice(i + 1));
      break;
    } else if (argv[i] === "--help") {
      io_out(1, io_bytes("usage: " + process.argv[1] + " [arguments]\n"));
      process.exit(0);
    } else if (argv[i] === "--threads" || argv[i] === "--gpu") {
      i += 1;
    } else {
      cli_args.push(argv[i]);
    }
  }
}

function bend_run(main) {
  cli(process.argv.slice(2));
  let code;
  try {
    code = io_run(main());
  } catch (e) {
    io_errs(e instanceof RangeError ? "bend: the machine stack overflowed" : String(e));
    code = 1;
  }
  process.exit(code);
}

function bend_run_value(main, show) {
  cli(process.argv.slice(2));
  try {
    io_out(1, io_bytes(show(main()) + "\n"));
  } catch (e) {
    io_errs(e instanceof RangeError ? "bend: the machine stack overflowed" : String(e));
    process.exit(1);
  }
  process.exit(0);
}
